export default function prepare({ body }) {
  const m = body?.message;
  if (!m || typeof m.text !== "string" || !m.text.trim() || !Number.isSafeInteger(m.chat?.id))
    throw Error("Send an image description as a text message");
  return { chatId: String(m.chat.id), style: { prompt: m.text } };
}

